<script setup lang="ts">
import { onMounted, ref } from 'vue';
import { Head } from '@inertiajs/vue3';
import ErpLayout from '@/layouts/ErpLayout.vue';
interface Flag { id:number; key:string; name:string; description:string|null; module_id:number|null; is_enabled:boolean; rollout_percentage:number; environment:string; is_system:boolean }
interface ModuleOption { id:number; name:string }
const flags=ref<Flag[]>([]); const modules=ref<ModuleOption[]>([]); const loading=ref(false); const saving=ref(false); const message=ref(''); const error=ref('');
const form=ref({name:'',key:'',description:'',module_id:'',is_enabled:false,rollout_percentage:100,environment:'all'});
function csrf():string { const row=document.cookie.split('; ').find(v=>v.startsWith('XSRF-TOKEN=')); return row?decodeURIComponent(row.slice(11)):''; }
function headers():Record<string,string>{return {Accept:'application/json','Content-Type':'application/json','X-Requested-With':'XMLHttpRequest','X-XSRF-TOKEN':csrf()};}
async function load():Promise<void>{loading.value=true;error.value='';try{const [f,m]=await Promise.all([fetch('/api/v1/backend/feature-flags',{credentials:'same-origin',headers:headers()}),fetch('/api/v1/backend/modules',{credentials:'same-origin',headers:headers()})]);if(!f.ok||!m.ok)throw new Error('Unable to load feature flags.');flags.value=(await f.json()).data??[];modules.value=(await m.json()).data??[];}catch(e){error.value=e instanceof Error?e.message:'Unable to load flags.';}finally{loading.value=false;}}
async function create():Promise<void>{saving.value=true;message.value='';error.value='';try{const response=await fetch('/api/v1/backend/feature-flags',{method:'POST',credentials:'same-origin',headers:headers(),body:JSON.stringify({...form.value,module_id:form.value.module_id?Number(form.value.module_id):null})});const data=await response.json();if(!response.ok)throw new Error(data.message??'Unable to create feature flag.');form.value={name:'',key:'',description:'',module_id:'',is_enabled:false,rollout_percentage:100,environment:'all'};message.value='Feature flag created.';await load();}catch(e){error.value=e instanceof Error?e.message:'Unable to save.';}finally{saving.value=false;}}
async function update(flag:Flag):Promise<void>{error.value='';try{const response=await fetch(`/api/v1/backend/feature-flags/${flag.id}`,{method:'PUT',credentials:'same-origin',headers:headers(),body:JSON.stringify({is_enabled:flag.is_enabled,rollout_percentage:flag.rollout_percentage,environment:flag.environment})});const data=await response.json();if(!response.ok)throw new Error(data.message??'Unable to update flag.');message.value=`${flag.key} updated.`;}catch(e){error.value=e instanceof Error?e.message:'Unable to update flag.';await load();}}
async function remove(flag:Flag):Promise<void>{if(flag.is_system||!window.confirm(`Delete feature flag ${flag.key}?`))return;error.value='';try{const response=await fetch(`/api/v1/backend/feature-flags/${flag.id}`,{method:'DELETE',credentials:'same-origin',headers:headers()});const data=await response.json();if(!response.ok)throw new Error(data.message??'Unable to delete flag.');message.value=`${flag.key} deleted.`;await load();}catch(e){error.value=e instanceof Error?e.message:'Unable to delete flag.';}}
onMounted(()=>{void load();});
</script>
<template><Head title="Feature Flags"/><ErpLayout><div class="space-y-5 p-4 md:p-6"><header class="flex flex-wrap items-center justify-between gap-3"><div><p class="text-xs font-semibold uppercase tracking-wider text-muted-foreground">Developer Controls</p><h1 class="text-2xl font-semibold">Feature Flags</h1><p class="mt-1 text-sm text-muted-foreground">Control feature rollout by environment and percentage. Flags never replace authorization.</p></div><button class="rounded-lg border px-3 py-2 text-sm" @click="load">Refresh</button></header><p v-if="message" class="rounded-lg border border-emerald-300 bg-emerald-50 p-3 text-sm text-emerald-800">{{message}}</p><p v-if="error" class="rounded-lg border border-red-300 bg-red-50 p-3 text-sm text-red-700">{{error}}</p><section class="rounded-xl border bg-card p-4"><h2 class="font-semibold">Register feature flag</h2><form class="mt-3 grid gap-3 md:grid-cols-2 xl:grid-cols-3" @submit.prevent="create"><label class="text-sm">Name<input v-model="form.name" required maxlength="150" class="mt-1 w-full rounded-lg border bg-background px-3 py-2"/></label><label class="text-sm">Key<input v-model="form.key" required pattern="[a-z0-9]+([._-][a-z0-9]+)*" maxlength="150" placeholder="module.feature.enabled" class="mt-1 w-full rounded-lg border bg-background px-3 py-2"/></label><label class="text-sm">Module<select v-model="form.module_id" class="mt-1 w-full rounded-lg border bg-background px-3 py-2"><option value="">No module</option><option v-for="module in modules" :key="module.id" :value="String(module.id)">{{module.name}}</option></select></label><label class="text-sm">Environment<select v-model="form.environment" class="mt-1 w-full rounded-lg border bg-background px-3 py-2"><option value="all">All environments</option><option value="local">Local</option><option value="testing">Testing</option><option value="staging">Staging</option><option value="production">Production</option></select></label><label class="text-sm">Rollout percentage<input v-model.number="form.rollout_percentage" type="number" min="0" max="100" class="mt-1 w-full rounded-lg border bg-background px-3 py-2"/></label><label class="flex items-center gap-2 pt-6 text-sm"><input v-model="form.is_enabled" type="checkbox"/> Enabled</label><label class="text-sm md:col-span-2 xl:col-span-3">Description<textarea v-model="form.description" rows="2" class="mt-1 w-full rounded-lg border bg-background px-3 py-2"/></label><div><button :disabled="saving" class="rounded-lg bg-primary px-4 py-2 text-sm font-medium text-primary-foreground">{{saving?'Saving…':'Create flag'}}</button></div></form></section><section class="overflow-hidden rounded-xl border bg-card"><div class="border-b p-4"><h2 class="font-semibold">Registered flags</h2><p class="text-xs text-muted-foreground">{{flags.length}} flags · system flags can be configured but not deleted</p></div><div v-if="loading" class="p-6 text-sm text-muted-foreground">Loading…</div><div v-else-if="!flags.length" class="p-6 text-sm text-muted-foreground">No feature flags registered.</div><div v-else class="overflow-x-auto"><table class="w-full text-left text-sm"><thead class="bg-muted/50 text-xs uppercase text-muted-foreground"><tr><th class="p-3">Flag</th><th class="p-3">Module</th><th class="p-3">Environment</th><th class="p-3">Rollout</th><th class="p-3">Enabled</th><th class="p-3">Action</th></tr></thead><tbody><tr v-for="flag in flags" :key="flag.id" class="border-t"><td class="p-3"><strong>{{flag.name}}</strong><div class="text-xs text-muted-foreground">{{flag.key}}</div><div v-if="flag.description" class="mt-1 max-w-md text-xs text-muted-foreground">{{flag.description}}</div></td><td class="p-3">{{modules.find(m=>m.id===flag.module_id)?.name??'—'}}</td><td class="p-3"><select v-model="flag.environment" class="rounded border bg-background px-2 py-1"><option value="all">All</option><option value="local">Local</option><option value="testing">Testing</option><option value="staging">Staging</option><option value="production">Production</option></select></td><td class="p-3"><input v-model.number="flag.rollout_percentage" type="number" min="0" max="100" class="w-20 rounded border bg-background px-2 py-1"/>%</td><td class="p-3"><input v-model="flag.is_enabled" type="checkbox" aria-label="Enable feature flag"/></td><td class="p-3"><div class="flex gap-2"><button class="rounded-lg border px-3 py-1.5 text-xs" @click="update(flag)">Save</button><button v-if="!flag.is_system" class="rounded-lg border border-red-300 px-3 py-1.5 text-xs text-red-700" @click="remove(flag)">Delete</button></div></td></tr></tbody></table></div></section></div></ErpLayout></template>
